      const c = client("jira");
      const wanted = [...users.map((u) => `user:${u}`), ...groups.map((g) => `group:${g}`)];
      const summary = `Add ${[...users, ...groups].join(", ")} to role ${args.role_id} in ${args.project_key}`;
